def priority(item, bins):
    s = bins - item
    n = len(bins)
    if item < 25:
        return -s * 1.0
    if item < 50:
        return np.where(s == 0, 1000.0, 100.0 - np.arange(n))
    return 100.0 - np.arange(n) * 1.0

